(function(root){const at=()=>new Date().toISOString(),other=p=>p==='Alice'?'Bob':'Alice';function msg(s,p,text,kind='assistant',taskId=null){s.rooms[p].push({id:s.seq++,at:at(),text,kind,taskId});}function evt(s,t,from,to,text){s.events.push({at:at(),taskId:t.id,from,to,text});}
function seed(){const s={seq:1,next:1,rooms:{Alice:[],Bob:[]},tasks:[],events:[]};for(const p of ['Alice','Bob'])msg(s,p,`我是你的个人管家。你只需要在这里说目标，我会整理任务、联系协作者的管家，把需要你决定的事带回来。\n这是脚本驱动的演示：可以试试下方建议，不会调用真实模型或 GitLab。`);return s;}
function send(s,p,text){text=text.trim();if(!text)throw Error('请输入消息');msg(s,p,text,'user');const dest=other(p);if(/(请|让|交给|帮我|安排|委派)/.test(text)&&/(Bob|Alice)/i.test(text)){const t={id:'T'+String(s.next++).padStart(3,'0'),requester:p,owner:dest,title:text.slice(0,100),status:'awaiting',attempt:0,head:null,verified:null};s.tasks.push(t);evt(s,t,p+'的管家',dest+'的管家','发送任务摘要与约束，未传递私人聊天记录');msg(s,p,`已把任务摘要发给${dest}的管家，等待对方接单。你的其他聊天不会随任务发送。`,'assistant',t.id);msg(s,dest,`${p}委派了一项任务。我只收到了任务摘要，没有读取对方的私人会话。请确认是否接单。`,'assistant',t.id);return t;}
if(/(进度|状态|在做什么|今天|汇总)/.test(text)){const mine=s.tasks.filter(t=>[t.requester,t.owner].includes(p));msg(s,p,mine.length?mine.map(t=>`${t.id}：${labels[t.status]} · ${t.title}`).join('\n'):'目前没有正在跟进的任务。你可以直接说“请'+dest+'修复 WUA 报告单位显示，并补测试”。');}
else if(/(隐私|私人|私下|不要转发|别转发)/.test(text))msg(s,p,'这条消息只留在你的演示会话中，不进入协作信封。注意：本页面的身份切换只是演示，两位角色的数据实际都在同一个浏览器中，不是真实隐私隔离。');
else msg(s,p,`我记在你的当前会话里了。这个 Demo 暂时只识别“请${dest}…”委派和“查看进度”等预设意图，不会真正理解或执行任意自然语言。`);}
const labels={awaiting:'等对方接单',working:'执行中',verifying:'等待核验',ready:'等你验收',completed:'已完成',failed:'CI 未通过',canceled:'已取消'};
function action(s,p,id,a){const t=s.tasks.find(t=>t.id===id);if(!t)throw Error('任务不存在');const owner=()=>{if(p!==t.owner)throw Error('请由资源负责人确认');},req=()=>{if(p!==t.requester)throw Error('请由派活人验收');},state=x=>{if(!x.includes(t.status))throw Error('状态已变化，请勿重复操作');};
if(a==='accept'){owner();state(['awaiting']);t.status='working';t.attempt++;evt(s,t,p+'的管家',t.requester+'的管家','负责人已接单，签发 attempt '+t.attempt);msg(s,p,'你已确认接单。我已安排代码 Worker 在模拟隔离工作区处理。无需另外打开执行会话。','assistant',id);msg(s,t.requester,`${p}已接单。我会继续跟进，只在需要你判断或有交付时回来。`,'assistant',id);}
else if(a==='publish'||a==='fail'){owner();state(['working']);t.head='demo-'+id+'-a'+t.attempt;t.status=a==='fail'?'failed':'verifying';msg(s,p,a==='fail'?'模拟 CI 失败，我已暂停交付。可以重试或取消，不会把失败当成完成。':'代码 Worker 已生成候选补丁，受控发布模块创建了模拟 MR。接下来独立核对当前提交与 CI。','assistant',id);evt(s,t,p+'的管家','核验器',a==='fail'?'模拟 CI 失败，停止交付':'提交候选 SHA '+t.head);}
else if(a==='verify'){owner();state(['verifying']);t.verified=t.head;t.status='ready';evt(s,t,'核验器',t.requester+'的管家','当前 SHA 与模拟 CI 一致，发送交付摘要');msg(s,p,'独立模拟核验通过。我把必要的交付证据发送给派活人的管家，不共享你的私人讨论。','assistant',id);msg(s,t.requester,'收到交付：模拟 MR 已准备好，当前提交与 CI 一致。请在这个窗口验收或退回。验收不会合并代码。','assistant',id);}
else if(a==='approve'){req();state(['ready']);if(t.verified!==t.head)throw Error('当前提交尚未核验');t.status='completed';evt(s,t,p+'的管家',t.owner+'的管家','派活人已验收指定提交，不自动合并');msg(s,p,'验收已记录，任务闭环。没有合并代码，也没有执行任何真实外部动作。','assistant',id);msg(s,t.owner,`${p}已验收这次交付，我已归档任务。`,'assistant',id);}
else if(a==='return'){req();state(['ready']);t.status='awaiting';t.verified=null;evt(s,t,p+'的管家',t.owner+'的管家','交付退回，需重新接单');msg(s,p,'已退回给对方管家，等待重新接单。','assistant',id);msg(s,t.owner,'派活人退回了交付，需要你重新确认接单。','assistant',id);}
else if(a==='retry'){owner();state(['failed']);t.status='working';t.attempt++;t.verified=null;msg(s,p,'已创建新的执行尝试，旧证据不能用于本次验收。','assistant',id);}
else if(a==='cancel'){if(![t.owner,t.requester].includes(p))throw Error('无权取消');state(['awaiting','working','verifying','ready','failed']);t.status='canceled';evt(s,t,p+'的管家',other(p)+'的管家','任务已取消，停止新动作');msg(s,p,'已取消后续工作。已产生的模拟产物保留在记录中。','assistant',id);msg(s,other(p),'对方取消了任务，我已停止后续推进。','assistant',id);}
else throw Error('未知操作');return t;}
const api={seed,send,action,labels};if(typeof module!=='undefined')module.exports=api;root.ChatHub=api;})(typeof window!=='undefined'?window:globalThis);
